// Gabarit Accueil, boite : un courriel devient un message normalise, quel que soit le logiciel de messagerie du client.
const SOURCES = { 'Nouvel e-mail Gmail': 'gmail', 'Nouvel e-mail Outlook': 'outlook', 'Nouvel e-mail IMAP': 'imap' };
const source = SOURCES[$prevNode.name] || 'imap';
const premier = (...v) => v.find((x) => typeof x === 'string' && x.trim()) || '';
const sortie = [];
for (const it of $input.all()) {
  const m = it.json || {};
  const de = (m.from && m.from.value && m.from.value[0]) || (m.from && m.from.emailAddress) || {};
  const brut = premier(de.address, m.from && m.from.address, typeof m.from === 'string' ? m.from : '');
  const i = brut.indexOf('<');
  const adresse = (i >= 0 ? brut.slice(i + 1, brut.indexOf('>')) : brut).trim().toLowerCase();
  const corps = premier(m.text, m.textPlain, m.body && m.body.content, m.bodyPreview, m.snippet);
  sortie.push({ json: {
    source: source,
    ref_externe: premier(m.messageId, m.internetMessageId, m.id),
    id_boite: premier(m.id),
    fil_externe: premier(m.threadId, m.conversationId),
    de_adresse: adresse,
    de_nom: premier(de.name).slice(0, 120),
    sujet: premier(m.subject).slice(0, 300),
    texte: corps.slice(0, 4000),
    recu_le: premier(m.date, m.receivedDateTime) || new Date().toISOString(),
    a_photo: !!(m.hasAttachments || (m.attachments && m.attachments.length)),
  } });
}
return sortie;

// Gabarit Accueil, boite : un message n'entre qu'une fois ; un client n'a qu'une conversation (p6:280-285).
const cfg = ($input.first() && $input.first().json) || {};
const org = $('Compte de cette copie').first().json.organisation_id;
// Fail-closed : tout ce qui n'est pas exactement faux reste en simulation ; un interrupteur coupe tout.
const simulation = cfg.simulation !== false;
const coupe = cfg.interrupteur_general === false || cfg.interrupteur_departement === false;
// Copie figee des filtres de lib/releveCanal.ts (comparee au code par le juge).
const AUTOMATIQUE = /^(no-?reply|ne-?pas-?repondre|donotreply|mailer-daemon|postmaster|notifications?|newsletter|bounce|noreply)[@.-]/i;
const INDESIRABLE = /(facture[s]? ?orange|newsletter|se désinscrire|unsubscribe|linkedin|no-reply)/i;
const PLATEFORMES = ['habitatpresto.com', 'travaux.com', 'quotatis.fr', 'starofservice.fr', 'mesdepanneurs.fr'];
const vus = new Set();
const sortie = [];
for (const it of $('Compte de cette copie').all()) {
  const m = it.json;
  const cle = 'em:' + org + ':' + m.ref_externe;
  const domaine = m.de_adresse.slice(m.de_adresse.indexOf('@') + 1);
  const plateforme = PLATEFORMES.some((p) => domaine === p || domaine.endsWith('.' + p));
  let motif = null;
  if (coupe) motif = 'interrupteur_coupe';
  else if (!m.de_adresse) motif = 'sans_expediteur';
  else if (!m.ref_externe) motif = 'sans_identifiant';
  else if (AUTOMATIQUE.test(m.de_adresse) && !plateforme) motif = 'automatique';
  else if (m.texte.trim().length < 12) motif = 'trop_court';
  else if (INDESIRABLE.test(m.sujet) && m.texte.length < 400 && !plateforme) motif = 'indesirable';
  else if (vus.has(cle)) motif = 'doublon';
  if (!motif) vus.add(cle);
  sortie.push({ json: Object.assign({}, m, { organisation_id: org, simulation: simulation, cle: cle, conversation_cle: plateforme ? 'p:' + m.ref_externe : 'c:' + m.de_adresse, canal_origine: plateforme ? 'plateforme_devis' : m.source, repondre_au_client: !plateforme, voie: motif ? 'ignorer' : 'deposer', motif: motif }) });
}
return sortie;

// Simulation : rien n'est ecrit dans la plateforme ; le depot prevu part au journal.
const prevus = $input.all().map((it) => ({ effet: 'deposer_message', organisation_id: it.json.organisation_id, cle: it.json.cle, conversation_cle: it.json.conversation_cle, canal_origine: it.json.canal_origine }));
return [{ json: { simulation: true, effets_prevus: prevus, effets_faits: [] } }];
